file_editor: {"command": "create", "file_text": "import json
import math
from pathlib import Path
from pyscipopt import Model, quicksum

# ── Load data ──────────────────────────────────────────────────────────────
data = json.loads(Path("/root/data.json").read_text())

vehicle_count = data["vehicle_count"]
vehicle_capacity = data["vehicle_capacity"]
penalty_weight = data["penalty_weight"]
depot_loc = {"latitude": data["depot"]["latitude"], "longitude": data["depot"]["longitude"]}

stations_data = data["stations"]
n = len(stations_data)

station_ids = [int(s["id"]) for s in stations_data]
net_target = {i: stations_data[i]["net_rebalancing_target"] for i in range(n)}
initial_bikes = {i: stations_data[i]["initial_bikes"] for i in range(n)}
station_cap = {i: stations_data[i]["station_capacity"] for i in range(n)}
station_loc = {i: {"latitude": stations_data[i]["latitude"], "longitude": stations_data[i]["longitude"]} for i in range(n)}

K = range(vehicle_count)
N = range(n)

# ── Great-circle distance ──────────────────────────────────────────────────
RADIUS = 3960.0

def great_circle_miles(a, b):
    lat1, lon1 = math.radians(a["latitude"]), math.radians(a["longitude"])
    lat2, lon2 = math.radians(b["latitude"]), math.radians(b["longitude"])
    phi1 = math.pi / 2.0 - lat1
    phi2 = math.pi / 2.0 - lat2
    cos_arc = math.sin(phi1) * math.sin(phi2) * math.cos(lon1 - lon2) + math.cos(phi1) * math.cos(phi2)
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * RADIUS

# ── Node definitions ───────────────────────────────────────────────────────
START = "depot_start"
END = "depot_end"

def node_location(node):
    if node in (START, END):
        return depot_loc
    return station_loc[int(node)]

# Build arcs and distances
from_nodes = [START] + list(N)
to_nodes = list(N) + [END]

# All arcs excluding (START, END) and self-loops
arcs = []
distances = {}
for i in from_nodes:
    for j in to_nodes:
        if i == j:
            continue
        if i == START and j == END:
            continue
        arcs.append((i, j))
        distances[i, j] = great_circle_miles(node_location(i), node_location(j))

# Station-to-station arcs (for MTZ)
station_arcs = [(i, j) for i in N for j in N if i != j]

# ── Build SCIP model ───────────────────────────────────────────────────────
model = Model("bike_rebalancing")
model.hideOutput()

# Reproducibility
for name in ["randomization/randomseedshift", "randomization/permutationseed", "randomization/lpseed"]:
    try:
        model.setParam(name, 0)
    except Exception:
        pass
for name in ["randomization/permutevars", "randomization/permuteconss"]:
    try:
        model.setParam(name, False)
    except Exception:
        pass
try:
    model.setParam("parallel/maxnthreads", 1)
except Exception:
    pass

# ── Decision variables ─────────────────────────────────────────────────────
# Arc variables: x[k, i, j] = 1 if vehicle k travels from i to j
x = {}
for k in K:
    for i, j in arcs:
        x[k, i, j] = model.addVar(vtype="B", name=f"x_{k}_{i}_{j}")

# Pickup / dropoff amounts per vehicle per station
pick = {}
drop = {}
for k in K:
    for i in N:
        pick[k, i] = model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"pick_{k}_{i}")
        drop[k, i] = model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"drop_{k}_{i}")

# Binary: 1 if vehicle k picks up at station i (0 = drop off)
pickup_ind = {}
for k in K:
    for i in N:
        pickup_ind[k, i] = model.addVar(vtype="B", name=f"pickup_ind_{k}_{i}")

# Load after visiting station i (for vehicle k)
load_after = {}
for k in K:
    for i in N:
        load_after[k, i] = model.addVar(vtype="C", lb=0, ub=vehicle_capacity, name=f"load_after_{k}_{i}")

# Start and end load for each vehicle
start_load = {}
end_load = {}
for k in K:
    start_load[k] = model.addVar(vtype="C", lb=0, ub=vehicle_capacity, name=f"start_load_{k}")
    end_load[k] = model.addVar(vtype="C", lb=0, ub=vehicle_capacity, name=f"end_load_{k}")

# MTZ order variables
order = {}
for k in K:
    for i in N:
        order[k, i] = model.addVar(vtype="C", lb=1, ub=n, name=f"order_{k}_{i}")

# Unmet rebalancing target per station
unmet = {}
for i in N:
    unmet[i] = model.addVar(vtype="C", lb=0, name=f"unmet_{i}")

# Visit indicator: 1 if vehicle k visits station i
visit = {}
for k in K:
    for i in N:
        visit[k, i] = quicksum(x[k, i, j] for j in to_nodes if j != i)

# ── Route structure constraints ────────────────────────────────────────────
M = vehicle_capacity

for k in K:
    # Must leave START exactly once
    model.addCons(quicksum(x[k, START, j] for j in N) == 1)
    # Must enter END exactly once
    model.addCons(quicksum(x[k, i, END] for i in N) == 1)

    # Flow conservation at each station
    for i in N:
        incoming = quicksum(x[k, j, i] for j in from_nodes if j != i)
        outgoing = quicksum(x[k, i, j] for j in to_nodes if j != i)
        model.addCons(incoming == outgoing)
        model.addCons(outgoing <= 1)  # visit at most once

    # Must visit at least one station
    model.addCons(quicksum(visit[k, i] for i in N) >= 1)

# ── MTZ subtour elimination ────────────────────────────────────────────────
for k in K:
    for i in N:
        for j in N:
            if i != j:
                model.addCons(order[k, i] - order[k, j] + n * x[k, i, j] <= n - 1)

# ── Load tracking via arc constraints ──────────────────────────────────────
for k in K:
    # From START: load_after[k, j] = start_load[k] + pick[k,j] - drop[k,j]
    for j in N:
        model.addCons(
            load_after[k, j] >= start_load[k] + pick[k, j] - drop[k, j] - M * (1 - x[k, START, j])
        )
        model.addCons(
            load_after[k, j] <= start_load[k] + pick[k, j] - drop[k, j] + M * (1 - x[k, START, j])
        )

    # Station-to-station: load_after[k, j] = load_after[k, i] + pick[k,j] - drop[k,j]
    for i in N:
        for j in N:
            if i != j:
                model.addCons(
                    load_after[k, j] >= load_after[k, i] + pick[k, j] - drop[k, j] - M * (1 - x[k, i, j])
                )
                model.addCons(
                    load_after[k, j] <= load_after[k, i] + pick[k, j] - drop[k, j] + M * (1 - x[k, i, j])
                )

    # To END: end_load[k] = load_after[k, i] (last station's load)
    for i in N:
        model.addCons(
            end_load[k] >= load_after[k, i] - M * (1 - x[k, i, END])
        )
        model.addCons(
            end_load[k] <= load_after[k, i] + M * (1 - x[k, i, END])
        )

# ── Pickup/dropoff mutual exclusion at each stop ───────────────────────────
for k in K:
    for i in N:
        # If pickup_ind = 1 → can only pick up; if 0 → can only drop off
        model.addCons(pick[k, i] <= M * pickup_ind[k, i])
        model.addCons(drop[k, i] <= M * (1 - pickup_ind[k, i]))
        # Only do something if visited
        model.addCons(pick[k, i] + drop[k, i] <= M * visit[k, i])

# ── Station-level aggregations and capacity ────────────────────────────────
for i in N:
    total_pick_i = quicksum(pick[k, i] for k in K)
    total_drop_i = quicksum(drop[k, i] for k in K)
    net_change_i = total_pick_i - total_drop_i

    # Final inventory bounds
    final_inventory = initial_bikes[i] - total_pick_i + total_drop_i
    model.addCons(final_inventory >= 0)
    model.addCons(final_inventory <= station_cap[i])

    # Unmet target: |net_target[i] - net_change_i| <= unmet[i]
    model.addCons(net_target[i] - net_change_i <= unmet[i])
    model.addCons(net_change_i - net_target[i] <= unmet[i])

# ── Objective ──────────────────────────────────────────────────────────────
travel_distance = quicksum(
    distances[i, j] * x[k, i, j] for k in K for i, j in arcs
)
total_unmet = quicksum(unmet[i] for i in N)
penalty = penalty_weight * total_unmet

model.setObjective(travel_distance + penalty, "minimize")

# ── Solve ──────────────────────────────────────────────────────────────────
model.setParam("limits/time", 300.0)
model.setParam("limits/gap", 0.001)
model.optimize()

status = str(model.getStatus()).lower()
if model.getNSols() == 0:
    raise RuntimeError(f"SCIP found no feasible solution; status={status}")

print(f"Solver status: {status}")
print(f"Objective: {model.getObjVal():.6f}")
print(f"Primal bound: {model.getPrimalbound():.6f}")
print(f"Dual bound: {model.getDualbound():.6f}")

# ── Extract solution ───────────────────────────────────────────────────────
def val(var):
    return model.getVal(var)

def is_one(var):
    return val(var) > 0.5

# Reconstruct routes
vehicle_routes = {}
for k in K:
    # Build outgoing mapping
    outgoing = {}
    for i, j in arcs:
        if is_one(x[k, i, j]):
            outgoing[i] = j
    # Trace route
    route = [START]
    cur = START
    while cur != END:
        if cur not in outgoing:
            raise RuntimeError(f"Vehicle {k}: route disconnected at {cur}")
        cur = outgoing[cur]
        route.append(cur)
    vehicle_routes[k] = route

# Build report
def node_label(node):
    if node == START:
        return "depot_start"
    if node == END:
        return "depot_end"
    return station_ids[int(node)]

report_vehicles = []
for k in K:
    route = vehicle_routes[k]
    stops = []
    for node in route[1:-1]:  # skip START and END
        i = int(node)
        stops.append({
            "station_id": station_ids[i],
            "bikes_picked_up": round(val(pick[k, i]), 10),
            "bikes_dropped_off": round(val(drop[k, i]), 10),
            "load_after_stop": round(val(load_after[k, i]), 10),
        })
    report_vehicles.append({
        "vehicle_id": k + 1,
        "start_load": round(val(start_load[k]), 10),
        "route": [node_label(n) for n in route],
        "stops": stops,
        "end_load": round(val(end_load[k]), 10),
    })

report_stations = []
for i in N:
    total_pick = round(sum(val(pick[k, i]) for k in K), 10)
    total_drop = round(sum(val(drop[k, i]) for k in K), 10)
    net_change = total_pick - total_drop
    unmet_val = round(val(unmet[i]), 10)
    report_stations.append({
        "station_id": station_ids[i],
        "net_rebalancing_target": float(net_target[i]),
        "total_bikes_picked_up": total_pick,
        "total_bikes_dropped_off": total_drop,
        "net_bike_change": net_change,
        "unmet_rebalancing_amount": unmet_val,
    })

# ── Validation ─────────────────────────────────────────────────────────────
print("\n─── Validation ───")

# 1. Recompute distances
recomputed_distance = 0.0
for k in K:
    r = vehicle_routes[k]
    for a, b in zip(r, r[1:]):
        recomputed_distance += distances[a, b]

model_distance = val(travel_distance)
print(f"Travel distance: model={model_distance:.6f}, recomputed={recomputed_distance:.6f}")
assert abs(recomputed_distance - model_distance) < 1e-6, "Distance mismatch"

# 2. Recompute load consistency
for k in K:
    r = vehicle_routes[k]
    load = val(start_load[k])
    print(f"Vehicle {k+1}: start_load={load:.1f}")
    for idx in range(1, len(r) - 1):
        i = int(r[idx])
        p = val(pick[k, i])
        d = val(drop[k, i])
        load = load + p - d
        model_load = val(load_after[k, i])
        assert abs(load - model_load) < 1e-6, f"Load mismatch at vehicle {k+1}, station {station_ids[i]}"
        assert 0 <= load <= vehicle_capacity + 1e-6, f"Load out of bounds at vehicle {k+1}, station {station_ids[i]}: {load}"
        assert (p < 1e-6) or (d < 1e-6), f"Both pick and drop at vehicle {k+1}, station {station_ids[i]}"
    end_l = val(end_load[k])
    assert abs(load - end_l) < 1e-6, f"End load mismatch vehicle {k+1}: {load} vs {end_l}"

# 3. Validate station capacity and unmet
total_unmet_recomp = 0.0
for i in N:
    total_p = sum(val(pick[k, i]) for k in K)
    total_d = sum(val(drop[k, i]) for k in K)
    final_inv = initial_bikes[i] - total_p + total_d
    assert 0 <= final_inv <= station_cap[i] + 1e-6, f"Station {station_ids[i]} final inventory {final_inv} out of [0, {station_cap[i]}]"
    net_ch = total_p - total_d
    unmet_recomp = abs(net_target[i] - net_ch)
    assert abs(unmet_recomp - val(unmet[i])) < 1e-6, f"Unmet mismatch station {station_ids[i]}"
    total_unmet_recomp += unmet_recomp
    if unmet_recomp > 1e-6:
        print(f"  Station {station_ids[i]}: target={net_target[i]}, actual={net_ch}, unmet={unmet_recomp:.1f}")

penalty_recomp = penalty_weight * total_unmet_recomp
objective_recomp = recomputed_distance + penalty_recomp
print(f"Objective: model={model.getObjVal():.6f}, recomputed={objective_recomp:.6f}")
assert abs(objective_recomp - model.getObjVal()) < 1e-6, "Objective mismatch"

print("All validations passed!")

# ── Write report ───────────────────────────────────────────────────────────
summary = {
    "objective": round(objective_recomp, 10),
    "travel_distance_miles": round(recomputed_distance, 10),
    "unmet_rebalancing_penalty": round(penalty_recomp, 10),
    "total_unmet_rebalancing_amount": round(total_unmet_recomp, 10),
}

report = {
    "summary": summary,
    "vehicles": report_vehicles,
    "stations": report_stations,
}

# Clean up tiny floating-point artifacts
def clean_value(v):
    if isinstance(v, float) and abs(v) < 1e-9:
        return 0.0
    return v

import copy
def clean_report(obj):
    if isinstance(obj, dict):
        return {k: clean_report(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [clean_report(item) for item in obj]
    elif isinstance(obj, float):
        return round(obj, 10)
    return obj

report = clean_report(report)

Path("/root/report.json").write_text(json.dumps(report, indent=2) + "\n")
print("\nreport.json written successfully!")", "path": "/root/solve.py"}: Editing /root/solve.py
